import { normalizeOrderNumber } from '../lib/order-number.js';

async function lookupSecure(request,env){
  if(request.method!=="POST")return fail("الطريقة غير مسموحة.",405);
  if(!rateLimit(request,"lookup",15))return Response.json({message:"تم تجاوز حد الاستعلامات. حاول بعد دقيقة."},{status:429,headers:{"retry-after":"60"}});
  const body=await request.json().catch(()=>({}));
  const order=normalizeOrderNumber(body.orderNumber||body.order_number||body.salla_reference_id);
  if(!/^\d{1,30}$/.test(order))return fail("أدخل رقم الطلب بالأرقام فقط.");
  const url=env.SUPABASE_URL||env.NEXT_PUBLIC_SUPABASE_URL,key=env.SUPABASE_SERVICE_ROLE_KEY;
  if(!url||!key)return fail("خدمة الاستعلام غير متاحة مؤقتًا.",503);
  const result=await fetch(url+"/rest/v1/orders?select=tracking_token&or="+encodeURIComponent("(order_number.eq."+order+",order_number.eq.#"+order+")")+"&limit=1",{headers:{apikey:key,authorization:"Bearer "+key}});
  if(!result.ok)return fail("تعذر تنفيذ الاستعلام.",502);
  const [found]=await result.json();
  if(!found?.tracking_token)return fail("لم يتم العثور على طلب مطابق للبيانات.",404);
  return Response.json({redirectTo:"/track/"+encodeURIComponent(found.tracking_token)},{headers:{"cache-control":"private, no-store"}});
}
