async function adminLogin(r,e){if(!ready(e))return fail("لم تُضبط بيانات Supabase أو قائمة المشرفين بعد.",503);let{email,password}=await r.json().catch(()=>({}));let a=await fetch(e.SUPABASE_URL+"/auth/v1/token?grant_type=password",{method:"POST",headers:{apikey:e.SUPABASE_ANON_KEY,"content-type":"application/json"},body:JSON.stringify({email,password})}),b=await a.json().catch(()=>({}));if(!a.ok||!b.access_token)return fail("بيانات الدخول غير صحيحة أو الحساب غير مفعّل.",401);if(!admins(b.user?.email||email,e))return fail("الحساب غير مصرح له بالإدارة.",403);return Response.json({ok:true},{headers:{"set-cookie":session+"="+encodeURIComponent(b.access_token)+"; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age="+Math.min(Number(b.expires_in||3600),3600)}})}
async function adminSession(r,e){if(!ready(e))return fail("Supabase غير مهيأ.",503);let t=cookie(r,session);if(!t)return fail("جلسة غير موجودة.",401);let a=await fetch(e.SUPABASE_URL+"/auth/v1/user",{headers:{apikey:e.SUPABASE_ANON_KEY,authorization:"Bearer "+decodeURIComponent(t)}}),u=await a.json().catch(()=>({}));return a.ok&&u.email&&admins(u.email,e)?Response.json({email:u.email}):fail("جلسة غير صالحة.",401)}
function adminLogout(){return Response.json({ok:true},{headers:{"set-cookie":session+"=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0"}})}
async function lookup(r,u,e){if(!rateLimit(r,"lookup",20))return Response.json({message:"تم تجاوز الحد المؤقت للاستعلامات. حاول بعد دقيقة."},{status:429,headers:{"retry-after":"60"}});let q=(u.searchParams.get("q")||"").trim();if(q.length<4)return fail("أدخل رقم طلب أو جوال صالح.");if(e.PUBLIC_LOOKUP_ENABLED!=="true"||!e.SUPABASE_SERVICE_ROLE_KEY)return fail("خدمة الاستعلام قيد التهيئة.",503);let by=/^[0-9+]+$/.test(q)&&q.length<=15?"customer_phone":"order_number",a=await fetch(e.SUPABASE_URL+"/rest/v1/orders?select=id,order_number,product_name,service_type,status,expires_at,warranty_expires_at,tracking_token&"+by+"=eq."+encodeURIComponent(q),{headers:{apikey:e.SUPABASE_SERVICE_ROLE_KEY,authorization:"Bearer "+e.SUPABASE_SERVICE_ROLE_KEY}});if(!a.ok)return fail("تعذر تنفيذ الاستعلام.",502);let orders=await a.json();if(by==="customer_phone")orders=orders.map(({tracking_token,...x})=>x);return Response.json({orders},{headers:{"cache-control":"private, max-age=3, must-revalidate","vary":"cf-connecting-ip"}})}
async function inboundEmail(r,e){const secret=e.INBOUND_EMAIL_SECRET||e.EMAIL_WEBHOOK_SECRET;if(!secret||r.headers.get("authorization")!=="Bearer "+secret)return Response.json({error:"Unauthorized"},{status:401});if(!rateLimit(r,"email-webhook",60))return Response.json({error:"Rate limited"},{status:429,headers:{"retry-after":"60"}});const {messageId,to,from,subject,textBody}=await r.json().catch(()=>({}));if(!messageId||!to||!from)return Response.json({error:"Missing email envelope"},{status:400});const now=Date.now();for(const[k,t]of deliveryIds)if(now-t>300000)deliveryIds.delete(k);if(deliveryIds.has(messageId))return Response.json({accepted:true,duplicate:true,messageId},{status:200});deliveryIds.set(messageId,now);const s=(String(subject||"")+"\n"+String(textBody||"")).slice(0,4000).toLowerCase(),blocked=/password|reset|forgot|change email|email changed|كلمة المرور|إعادة تعيين|تغيير البريد/.test(s),category=blocked?"critical_blocked":/new (login|device)|login verification|verify|sign-in|تأكيد دخول|جهاز جديد/.test(s)?"login_notification":"unmatched";return Response.json({accepted:true,messageId,serviceType:/crunchyroll/.test(s)?"crunchyroll":/chatgpt|openai/.test(s)?"chatgpt":"general_subscription",category,customerVisible:false,bodyInspectedChars:Math.min(String(textBody||"").length,4000)},{status:202})}
